_AMOUNT_ONLY_RE = re.compile(r"^[\d\$\.,\s%]+$")
_LEADING_AMOUNT_RE = re.compile(
    r"^\$"  # currency symbol: "$1,234.00 Balance"
    r"|^\d[\d,]*\.\d{2}\b"  # bare decimal amount: "1,234.00 Balance"
    r"|^\d{1,3}(?:,\d{3})+\b"  # comma-grouped amount: "1,234 Balance"
    r"|^\d[\d.,]*\s*%"  # percentage: "70% Available"
)


def is_plausible_creditor_line(line: str) -> bool:
    line = line.strip()
    if len(line) < 2 or len(line) > 80:
        return False
    if _SKIP_CREDITOR_LINES.match(line):
        return False
    if is_city_state_line(line):
        return False
    if re.match(r"^\d{3}[-\s]?\d{2}[-\s]?\d{4}$", line):
        return False
    # Reject amount/percentage lines, but keep creditor names that merely start
    # with a digit ("1ST FRANKLIN FINANCIAL", "4FRONT CREDIT UNION").
    if _AMOUNT_ONLY_RE.match(line) or _LEADING_AMOUNT_RE.match(line):
        return False
    if line.lower().startswith("http"):
        return False
    return bool(re.search(r"[A-Za-z]", line))

