_UNKNOWN_CREDITOR = frozenset({"unknown", "unknown creditor", "n/a", "na"})


def _normalize_key_part(value: str) -> str:
    """Case- and whitespace-insensitive form used for identity comparisons."""
    return re.sub(r"\s+", " ", (value or "").strip()).lower()


def tradeline_dedupe_key(creditor: str, account_number: str) -> str:
    """Identity of a tradeline: creditor + account number, ignoring letter-case."""
    return f"{_normalize_key_part(creditor)}|{_normalize_key_part(account_number)}"


def is_junk_creditor_name(creditor: str) -> bool:
    name = (creditor or "").strip()
    if not name:
        return True
    if not is_plausible_creditor_line(name):
        return True
    if _normalize_key_part(name) in _UNKNOWN_CREDITOR:
        return True

