def dedupe_tradelines(tradelines: List[ParsedTradeline]) -> List[ParsedTradeline]:
    seen: set[str] = set()
    out: List[ParsedTradeline] = []
    for tl in tradelines:
        key = tradeline_dedupe_key(tl.creditor, tl.account_number)
        if key in seen:
            continue
        seen.add(key)
        out.append(tl)
    return out


def dedupe_inquiries(inquiries: List[ParsedInquiry]) -> List[ParsedInquiry]:
    seen: set[str] = set()
    out: List[ParsedInquiry] = []
    for inq in inquiries:
        key = f"{_normalize_key_part(inq.name)}|{inq.date or ''}"
        if key in seen:
            continue
        seen.add(key)
        out.append(inq)
    return out

